# Secret names for this project - names only, no values (those are in the secret manager).
# Lines: NAME               -> stored as <prefix>_NAME
#        NAME = STORED_NAME -> explicit stored name
project: apps
file: ~/.config/talk-to-terminal/config.env
# prefix: iphone_dict_capture   (default: folder name)

DICTATION_HOST
DICTATION_PORT
DICTATION_SHARED_SECRET
DICTATION_BACKEND
DICTATION_TYPE_DELAY_MS
DICTATION_CHUNK_SIZE
DICTATION_CHUNK_PAUSE_MS
DICTATION_INJECTION_MODE
DICTATION_PASTE_KEY_COMBO
